import "server-only";
import { readFile } from "node:fs/promises";
import path from "node:path";
import type { ChecklistPdfAssets } from "./checklist-pdf";

const ASSET_ROOT = path.join(process.cwd(), "assets");

let cached: Promise<ChecklistPdfAssets> | null = null;

/** Font and logo of the document checklist PDF (generated by node scripts/generate-logo-assets.mjs); kept in memory for the life of the process. */
export function loadChecklistPdfAssets(): Promise<ChecklistPdfAssets> {
  if (!cached) {
    const pending = (async () => {
      const [regularFont, logoPng] = await Promise.all([
        readFile(path.join(ASSET_ROOT, "fonts", "LiberationSans-Regular.ttf")),
        readFile(path.join(ASSET_ROOT, "brand", "logo.png")),
      ]);
      return { regularFont: new Uint8Array(regularFont), logoPng: new Uint8Array(logoPng) };
    })();
    // If reading fails, it can be retried on the next request.
    pending.catch(() => {
      cached = null;
    });
    cached = pending;
  }
  return cached;
}
